  <script>
    (() => {
      const leg1 = document.getElementById('leg1');
      const leg2 = document.getElementById('leg2');
      const foot1 = document.getElementById('foot1');
      const foot2 = document.getElementById('foot2');
      const crankArm = document.getElementById('crankArm');
      const pedalA = document.getElementById('pedalA');
      const pedalB = document.getElementById('pedalB');

      const cx = 480, cy = 414, radius = 34;
      const hip1 = { x: 431, y: 291 };
      const hip2 = { x: 455, y: 292 };

      function update(time) {
        const angle = time * 0.0045;
        const points = [
          { x: cx + Math.cos(angle) * radius, y: cy + Math.sin(angle) * radius },
          { x: cx + Math.cos(angle + Math.PI) * radius, y: cy + Math.sin(angle + Math.PI) * radius }
        ];

        function drawLeg(path, foot, hip, p, bendSide) {
          const dx = p.x - hip.x;
          const dy = p.y - hip.y;
          const len = Math.hypot(dx, dy) || 1;
          const bend = {
            x: (hip.x + p.x) / 2 + (-dy / len) * 20 * bendSide,
            y: (hip.y + p.y) / 2 + (dx / len) * 20 * bendSide
          };
          const ankle = {
            x: p.x - Math.cos(angle) * 9,
            y: p.y - Math.sin(angle) * 9
          };
          path.setAttribute('d',
            `M${hip.x} ${hip.y} Q${bend.x} ${bend.y} ${ankle.x} ${ankle.y} L${p.x} ${p.y}`
          );
          foot.setAttribute('cx', p.x);
          foot.setAttribute('cy', p.y);
          foot.setAttribute('transform', `rotate(${Math.sin(angle) * 12} ${p.x} ${p.y})`);
        }

        drawLeg(leg1, foot1, hip1, points[0], 1);
        drawLeg(leg2, foot2, hip2, points[1], -1);

        const armEnd = { x: cx + Math.cos(angle) * radius, y: cy + Math.sin(angle) * radius };
        crankArm.setAttribute('x2', armEnd.x);
        crankArm.setAttribute('y2', armEnd.y);
        pedalA.setAttribute('x1', armEnd.x - 13);
        pedalA.setAttribute('x2', armEnd.x + 13);
        pedalA.setAttribute('y1', armEnd.y);
        pedalA.setAttribute('y2', armEnd.y);
        const other = { x: cx - Math.cos(angle) * radius, y: cy - Math.sin(angle) * radius };
        pedalB.setAttribute('x1', other.x - 13);
        pedalB.setAttribute('x2', other.x + 13);
        pedalB.setAttribute('y1', other.y);
        pedalB.setAttribute('y2', other.y);

        requestAnimationFrame(update);
      }
      requestAnimationFrame(update);
    })();
  </script>
